// ❌ 콜백 지옥: 단계마다 중첩 + 상태가 콜백에 흩어짐
loadUser(id, (user) => {
  loadInventory(user, (inv) => {
    loadPrices(inv, (prices) => {
      render(user, inv, prices, (html) => {
        send(html);
      });
    });
  });
});
// + 각 단계 에러처리까지 넣으면 피라미드가 더 깊어짐(파멸의 피라미드)

// 콜백 지옥을 '평탄한 상태머신'으로 편 것
enum State { LOAD_USER, LOAD_INV, LOAD_PRICE, DONE };
struct Session {
    State state = LOAD_USER;
    User user; Inventory inv; Prices prices;   // 진행 중 데이터를 '필드'에 저장
    void onResult(Result r) {
        switch (state) {                        // 지금 단계 보고 다음으로
        case LOAD_USER:  user = r;   state = LOAD_INV;   loadInventory(user); break;
        case LOAD_INV:   inv = r;    state = LOAD_PRICE; loadPrices(inv);     break;
        case LOAD_PRICE: prices = r; state = DONE;       send(render(user,inv,prices)); break;
        }
    }
};

// ✅ 코루틴: 컴파일러가 상태머신을 자동 생성. 코드는 선형(동기처럼 읽힘)
task<void> handle(int id) {
    User      user   = co_await loadUser(id);        // 여기서 suspend, 응답 오면 resume
    Inventory inv    = co_await loadInventory(user);
    Prices    prices = co_await loadPrices(inv);
    co_await send(render(user, inv, prices));
}
// 중첩 0, 상태는 그냥 지역변수, 에러는 평범한 try/catch.
// 읽기는 동기처럼, 실행은 비동기(스레드 안 막음).
